DO $cleanup_guard$ BEGIN
 IF current_database()<>'dental_lab' OR current_user<>'dental_lab_migrator'
 OR (SELECT count(*) FROM public.accounts)<>3 OR (SELECT count(*) FROM public.orders)<>4
 OR EXISTS(SELECT 1 FROM public.accounts WHERE email_key NOT IN ('owner@example.invalid','clinic1@example.invalid','clinic2@example.invalid'))
 OR EXISTS(SELECT 1 FROM public.orders WHERE id NOT IN ('40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004'))
 THEN RAISE EXCEPTION 'CONCURRENCY_CLEANUP_UNEXPECTED_DATA_STOP'; END IF;
END; $cleanup_guard$;
SET CONSTRAINTS ALL DEFERRED;
DELETE FROM public.work_links WHERE source_order_id='40000000-0000-4000-8000-000000000001' AND child_order_id IN ('40000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004');
DELETE FROM public.order_requests WHERE order_id='40000000-0000-4000-8000-000000000002' AND kind='cancellation' AND requested_by='10000000-0000-4000-8000-000000000003';
UPDATE public.orders SET status='accepted',manufacturing_version_id=NULL WHERE id IN ('40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004');
DELETE FROM public.order_versions WHERE id IN ('60000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000002','60000000-0000-4000-8000-000000000003','60000000-0000-4000-8000-000000000004');
DELETE FROM public.orders WHERE id IN ('40000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000004');
DELETE FROM public.catalog_reference_snapshots WHERE id IN ('30000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000003');
DELETE FROM public.clinics WHERE id IN ('20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002');
DELETE FROM public.owner_slot WHERE singleton=1 AND account_id='10000000-0000-4000-8000-000000000001';
DELETE FROM public.accounts WHERE id IN ('10000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003');
SET CONSTRAINTS ALL IMMEDIATE;
